 "content": "def transform(grid):
    """Fill one-cell horizontal gaps and extend the bars/vertical markers."""
    out = [row[:] for row in grid]
    h = len(grid)
    if not h:
        return out
    w = len(grid[0])

    # A single zero bracketed by the same color is a gap in a horizontal bar.
    gaps = []
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            if row[c] == 0 and row[c - 1] != 0 and row[c - 1] == row[c + 1]:
                color = row[c - 1]
                out[r][c] = color
                gaps.append((r, c, color))

    # Continue each bar's gap upward through empty cells to the edge or next bar.
    for r, c, color in gaps:
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color

    # Extend bottom-edge vertical marker runs upward until they meet the bars.
    for c in range(w):
        r = h - 1
        color = grid[r][c]
        if color == 0:
            continue
        while r >= 0 and grid[r][c] == color:
            r -= 1
        r += 1  # top cell of the contiguous bottom run
        rr = r - 1
        while rr >= 0 and out[rr][c] == 0:
            out[rr][c] = color
            rr -= 1
    return out
